182		private evaluateRead(command: unknown): StoreResult<unknown> {
183			const prepared = prepareStorageAdapterCommand(command);
184			if (!prepared.ok) return prepared;
185			if (prepared.value.command.kind !== "readHead" && prepared.value.command.kind !== "readGenerationPage") {
186				return { ok: false, reason: "INVALID_ARGUMENT" };
187			}
188			const facts = this.readFacts(prepared.value);
189			if (!facts.ok) {
190				return evaluateStorageAdapterCommand(prepared.value, [{ kind: "store-closed" }]).result;
191			}
192			return evaluateStorageAdapterCommand(prepared.value, facts.value).result;
193		}
194	
195		private readFacts(prepared: PreparedStorageAdapterCommand): StoreResult<readonly StorageAdapterFact[]> {
196			if (prepared.command.kind === "readHead") {
197				const head = this.owner.readHead(prepared.command.objectId);
198				if (!head.ok) return head;
199				return {
200					ok: true,
201					value: [
202						{
203							headRecord: head.value.kind === "none" ? null : encodeHeadRecordV1(head.value),
204							kind: "head",
205							objectId: prepared.command.objectId,
206						},
207					],
208				};
209			}
210			if (prepared.command.kind !== "readGenerationPage") return { ok: true, value: [] };
211			const requirement = prepared.requirements[0];
212			if (requirement?.kind !== "generation-page") return { ok: true, value: [] };
213			const generations = this.owner.readGenerationPage(
214				requirement.objectId,
215				requirement.afterGenerationId,
216				requirement.limitPlusOne
217			);
218			if (!generations.ok) return generations;
219			return {
220				ok: true,
221				value: [
222					{
223						afterGenerationId: requirement.afterGenerationId,
224						generationRecords: generations.value.map(encodeGenerationRecordV1),
225						kind: "generation-page",
226						objectId: requirement.objectId,
227					},
228				],
229			};
230		}
231	}
232	
233	function commandWithKind(kind: "readGenerationPage", input: unknown): unknown {
234		if (typeof input !== "object" || input === null || Array.isArray(input)) return { kind, invalidInput: input };
235		const descriptors = Object.getOwnPropertyDescriptors(input);
236		if (Object.prototype.hasOwnProperty.call(descriptors, "kind")) return { kind, invalidInput: true };
237		const command = { kind } as Record<PropertyKey, unknown>;
238		Object.defineProperties(command, descriptors);
239		return command;
240	}
